var scenario = pm.iterationData.get("scenario");
var iterTitle = pm.iterationData.get("title");
var timestamp = Date.now().toString();

var dynamicTitle = iterTitle;

if (scenario === "valid") {

    dynamicTitle = iterTitle + " " + timestamp;
} else if (scenario === "edge") {

    var base = iterTitle.substring(0, iterTitle.length - timestamp.length);
    dynamicTitle = base + timestamp;
}


pm.variables.set("dynamicTitle", dynamicTitle);
